#define main oldmain
#include "../four/solve.cpp"
#undef main
// bits: 1 geometric predecessor, 2 non-dead predecessor, 4 WDL predecessor,
// 8 legal capture from4, 16 WDL capture from4, 32 legal reach from4, 64 WDL reach from4.
int main(){init();setup();load(); const int T=4;vector<vector<vector<uint8_t>>> a(T);for(auto &x:a){x.resize(6);for(int j=0;j<6;j++)x[j].resize(ts[j].sz);}atomic<int> index{0};vector<thread> tt;for(int k=0;k<T;k++)tt.emplace_back([&,k]{for(;;){int id=index++;if(id>=int(ts.size()))break;auto&t=ts[id];for(U i=0;i<(U)t.sz;i++){int z=t.v[i];if(z==INV)continue;auto p=dec(t,i);moves(t,p,[&](Move m,Pos v){if(id>=6&&m.cap<0)return;auto [j,q]=child(t,p,m,v);if(j>=6)return;auto x=enc(ts[j],q);int zz=pc(ts[j].v[x]);if(q.turn!=1-p.turn)zz=-zz;uint8_t mask=1;if(z!=DEAD){mask|=2;if(id>=6)mask|=8;if(z==zz){mask|=4;if(id>=6)mask|=16;}}a[k][j][x]|=mask;},id>=6);}cerr<<t.name<<" done\n";}});for(auto &x:tt)x.join();vector<vector<uint8_t>> mark(6);for(int j=0;j<6;j++){mark[j].resize(ts[j].sz);for(U i=0;i<(U)ts[j].sz;i++)for(int k=0;k<T;k++)mark[j][i]|=a[k][j][i];}
// restore color exchange for self-dual KvK, including predecessor flags.
auto sym=[&](){for(U i=0;i<(U)ts[0].sz;i++){Pos p=dec(ts[0],i);swap(p.s[0],p.s[1]);p.s[0]^=56;p.s[1]^=56;p.turn^=1;auto j=enc(ts[0],p);mark[0][j]|=mark[0][i];}};sym();
for(int b:{8,16}){int rb=b*4;vector<pair<int,U>> q;for(int j=0;j<6;j++)for(U i=0;i<(U)ts[j].sz;i++)if(mark[j][i]&b){mark[j][i]|=rb;q.push_back({j,i});}for(size_t h=0;h<q.size();h++){auto [j,i]=q[h];auto&t=ts[j];int z=t.v[i];if(z==DEAD)continue;auto p=dec(t,i);moves(t,p,[&](Move m,Pos v){auto [k,r]=child(t,p,m,v);auto x=enc(ts[k],r);int zz=pc(ts[k].v[x]);if(r.turn!=1-p.turn)zz=-zz;if((b==8||z==zz)&&!(mark[k][x]&rb))mark[k][x]|=rb,q.push_back({k,x});});}sym();}
ofstream miss("position_barriers.tsv");miss<<"material\tWDL\tflags\tFEN\n";cout<<"material,WDL,positions,legal_reach4,opt_reach4,no_geometric_pred,no_game_pred,no_opt_pred,opt_only_exclusion4,no_opt_pred_but_game_pred\n";for(int j=0;j<6;j++){auto&t=ts[j];long cnt[3][8]={};for(U i=0;i<(U)t.sz;i++){int z=t.v[i];if(z==INV)continue;int v=pc(z)+1,w=t.wk==16?4:2,m=mark[j][i];bool f[]={true,bool(m&32),bool(m&64),!(m&1),!(m&2),!(m&4),bool(m&32)&&!(m&64),bool(m&2)&&!(m&4)};for(int h=0;h<8;h++)cnt[v][h]+=w*f[h];if(!(m&64)||!(m&4))miss<<t.name<<'\t'<<v-1<<'\t'<<m<<'\t'<<fen(t,dec(t,i))<<'\n';}for(int z=0;z<3;z++)if(cnt[z][0]){cout<<t.name<<","<<z-1;for(auto c:cnt[z])cout<<","<<c;cout<<"\n";}}
}
